    [FormDataSourceEventHandler(formDataSourceStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine), FormDataSourceEventType::Created)]
    public static void RetailPeriodicDiscountLine_OnCreated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        RetailPeriodicDiscountLine retailPeriodicDiscountLine = sender.cursor();

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
            retailPeriodicDiscountLine is GUPMarginComponentPriceAdjustmentLine)
        {
            sender.write();

            GUPMarginComponentPriceAdjustmentLine marginComponentPriceAdjustLine = retailPeriodicDiscountLine;

            if (!marginComponentPriceAdjustLine.LinePricingRule)
            {
                Args args = new Args();
                args.caller(sender.formRun());
                args.record(marginComponentPriceAdjustLine);

                new MenuFunction(menuItemDisplayStr(GUPPriceAdjustPriceAttributeGroupEdit), MenuItemType::Display).run(args);
            }
        }
    }
